<?php
declare(strict_types=1);
require_once __DIR__ . '/db.php';
require_once __DIR__ . '/session.php';
requireAdmin();

$message=''; $messageType='error';
if ($_SERVER['REQUEST_METHOD']==='POST') {
    $name=trim((string)($_POST['name']??''));
    $category=trim((string)($_POST['category']??''));
    $price=(float)($_POST['price']??0);
    $description=trim((string)($_POST['description']??''));
    if ($name==='' || $category==='' || $price<=0) $message='Please enter product name, category and a valid price.';
    elseif (!isset($_FILES['photo1'],$_FILES['photo2'],$_FILES['photo3'])) $message='Please select all 3 product photos.';
    else {
        $files=[$_FILES['photo1'],$_FILES['photo2'],$_FILES['photo3']]; $paths=[]; $ok=true;
        $allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];
        foreach($files as $file){
            if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK || (int)$file['size']>5*1024*1024 || @getimagesize($file['tmp_name'])===false){$ok=false;break;}
            $mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);
            if(!isset($allowed[$mime])){$ok=false;break;}
            $filename=bin2hex(random_bytes(12)).'.'.$allowed[$mime];
            $destination=__DIR__.'/uploads/products/'.$filename;
            if(!move_uploaded_file($file['tmp_name'],$destination)){$ok=false;break;}
            $paths[]='uploads/products/'.$filename;
        }
        if(!$ok || count($paths)!==3){ foreach($paths as $p) @unlink(__DIR__.'/'.$p); $message='Each photo must be JPG, PNG or WEBP and no larger than 5 MB.'; }
        else {
            $stmt=$conn->prepare('INSERT INTO products (name,category,price,description,image1,image2,image3) VALUES (?,?,?,?,?,?,?)');
            $stmt->bind_param('ssdssss',$name,$category,$price,$description,$paths[0],$paths[1],$paths[2]);
            if($stmt->execute()){ $message='Product added successfully.'; $messageType='success'; }
            else { foreach($paths as $p) @unlink(__DIR__.'/'.$p); $message='Unable to add the product. Please try again.'; }
            $stmt->close();
        }
    }
}
?>
